def priority(item: float, bins: np.ndarray) -> np.ndarray:
    import numpy as np
    remainder = bins % item
    return np.where(bins >= item, -remainder, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    import numpy as np
    return np.where(bins >= item, np.floor_divide(bins, item), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    import numpy as np
    return np.where(bins >= item, bins - item, -np.inf)
